begin;
create table public.diagnostics(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,repair_id uuid not null,summary text not null,created_by uuid not null references auth.users(id),version integer not null default 1,created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,repair_id) references public.repairs(tenant_id,id));
create table public.quotes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,repair_id uuid not null,revision integer not null,status text not null default 'draft' check(status in ('draft','published','accepted','rejected','expired','replaced')),valid_until timestamptz,total_minor bigint not null default 0 check(total_minor>=0),currency text not null default 'COP',created_by uuid not null references auth.users(id),request_id uuid not null,published_at timestamptz,responded_at timestamptz,version integer not null default 1,created_at timestamptz not null default now(),unique(tenant_id,id),unique(tenant_id,repair_id,revision),unique(tenant_id,request_id),foreign key(tenant_id,repair_id) references public.repairs(tenant_id,id));
create table public.quote_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,quote_id uuid not null,label text not null,quantity integer not null check(quantity>0),unit_minor bigint not null check(unit_minor>=0),foreign key(tenant_id,quote_id) references public.quotes(tenant_id,id));
create table public.quote_responses(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,quote_id uuid not null,response text not null check(response in ('accepted','rejected')),actor_id uuid not null references auth.users(id),request_id uuid not null unique,created_at timestamptz not null default now(),unique(quote_id),foreign key(tenant_id,quote_id) references public.quotes(tenant_id,id));
alter table public.diagnostics enable row level security;alter table public.quotes enable row level security;alter table public.quote_items enable row level security;alter table public.quote_responses enable row level security;
revoke all on public.diagnostics,public.quotes,public.quote_items,public.quote_responses from public,anon,authenticated;grant select on public.diagnostics,public.quotes,public.quote_items,public.quote_responses to authenticated;
create policy diagnostics_read on public.diagnostics for select to authenticated using(private.can_read_repair(tenant_id,repair_id));
create policy quotes_read on public.quotes for select to authenticated using(private.can_read_repair(tenant_id,repair_id));
create policy quote_items_read on public.quote_items for select to authenticated using(exists(select 1 from public.quotes q where q.tenant_id=quote_items.tenant_id and q.id=quote_items.quote_id));
create policy quote_responses_read on public.quote_responses for select to authenticated using(exists(select 1 from public.quotes q where q.tenant_id=quote_responses.tenant_id and q.id=quote_responses.quote_id));
create function private.save_diagnostic(p_tenant uuid,p_repair uuid,p_summary text) returns uuid language plpgsql security definer set search_path='' as $$declare v uuid;begin perform private.assert_write(p_tenant,array['admin','advisor','technician']);if not private.can_read_repair(p_tenant,p_repair) then raise exception 'Repair unavailable' using errcode='42501';end if;insert into public.diagnostics(tenant_id,repair_id,summary,created_by) values(p_tenant,p_repair,trim(p_summary),auth.uid()) returning id into v;perform private.audit(p_tenant,'diagnostic.created',v);return v;end$$;
create function private.create_quote(p_tenant uuid,p_repair uuid,p_items jsonb,p_valid_until timestamptz,p_request_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare v uuid;v_revision integer;v_total bigint;begin perform private.assert_write(p_tenant,array['admin','advisor']);select id into v from public.quotes where tenant_id=p_tenant and request_id=p_request_id;if found then return v;end if;if p_valid_until<=now() or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Invalid quote' using errcode='23514';end if;select coalesce(sum((x->>'quantity')::integer*(x->>'unit_minor')::bigint),0) into v_total from jsonb_array_elements(p_items) x where (x->>'quantity')::integer>0 and (x->>'unit_minor')::bigint>=0;select coalesce(max(revision),0)+1 into v_revision from public.quotes where tenant_id=p_tenant and repair_id=p_repair;insert into public.quotes(tenant_id,repair_id,revision,valid_until,total_minor,created_by,request_id) values(p_tenant,p_repair,v_revision,p_valid_until,v_total,auth.uid(),p_request_id) returning id into v;insert into public.quote_items(tenant_id,quote_id,label,quantity,unit_minor) select p_tenant,v,trim(x->>'label'),(x->>'quantity')::integer,(x->>'unit_minor')::bigint from jsonb_array_elements(p_items) x;perform private.audit(p_tenant,'quote.draft_created',v);return v;end$$;
create function private.publish_quote(p_tenant uuid,p_quote uuid,p_expected_version integer) returns integer language plpgsql security definer set search_path='' as $$declare q public.quotes%rowtype;begin perform private.assert_write(p_tenant,array['admin','advisor']);select * into q from public.quotes where tenant_id=p_tenant and id=p_quote for update;if not found or q.status<>'draft' or q.version<>p_expected_version or q.valid_until<=now() then raise exception 'Quote cannot be published' using errcode='40001';end if;update public.quotes set status='replaced',version=version+1 where tenant_id=p_tenant and repair_id=q.repair_id and status='published';update public.quotes set status='published',published_at=now(),version=version+1 where id=p_quote;perform private.audit(p_tenant,'quote.published',p_quote);insert into private.outbox(tenant_id,event_type,aggregate_id,payload) values(p_tenant,'quote.published',p_quote,jsonb_build_object('repair_id',q.repair_id));return q.version+1;end$$;
create function private.respond_quote(p_tenant uuid,p_quote uuid,p_response text,p_request_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare q public.quotes%rowtype;v uuid;begin
 select id into v from public.quote_responses where request_id=p_request_id;if found then return v;end if;
 select * into q from public.quotes where tenant_id=p_tenant and id=p_quote for update;
 if not found or not private.owns_repair(p_tenant,q.repair_id) then raise exception 'Quote unavailable' using errcode='42501';end if;
 if q.status<>'published' or q.valid_until<=now() then raise exception 'Quote not current' using errcode='23514';end if;
 if p_response not in ('accepted','rejected') then raise exception 'Invalid response' using errcode='23514';end if;
 insert into public.quote_responses(tenant_id,quote_id,response,actor_id,request_id) values(p_tenant,p_quote,p_response,auth.uid(),p_request_id) returning id into v;
 update public.quotes set status=p_response,responded_at=now(),version=version+1 where id=p_quote;
 perform private.audit(p_tenant,'quote.'||p_response,p_quote);return v;end$$;
create function public.respond_quote(p_tenant uuid,p_quote uuid,p_response text,p_request_id uuid) returns uuid language sql security invoker set search_path='' as $$select private.respond_quote(p_tenant,p_quote,p_response,p_request_id);$$;
create function public.save_diagnostic(p_tenant uuid,p_repair uuid,p_summary text) returns uuid language sql security invoker set search_path='' as $$select private.save_diagnostic(p_tenant,p_repair,p_summary);$$;create function public.create_quote(p_tenant uuid,p_repair uuid,p_items jsonb,p_valid_until timestamptz,p_request_id uuid) returns uuid language sql security invoker set search_path='' as $$select private.create_quote(p_tenant,p_repair,p_items,p_valid_until,p_request_id);$$;create function public.publish_quote(p_tenant uuid,p_quote uuid,p_expected_version integer) returns integer language sql security invoker set search_path='' as $$select private.publish_quote(p_tenant,p_quote,p_expected_version);$$;
revoke all on function private.respond_quote(uuid,uuid,text,uuid),public.respond_quote(uuid,uuid,text,uuid),private.save_diagnostic(uuid,uuid,text),public.save_diagnostic(uuid,uuid,text),private.create_quote(uuid,uuid,jsonb,timestamptz,uuid),public.create_quote(uuid,uuid,jsonb,timestamptz,uuid),private.publish_quote(uuid,uuid,integer),public.publish_quote(uuid,uuid,integer) from public,anon;grant execute on function private.respond_quote(uuid,uuid,text,uuid),public.respond_quote(uuid,uuid,text,uuid),private.save_diagnostic(uuid,uuid,text),public.save_diagnostic(uuid,uuid,text),private.create_quote(uuid,uuid,jsonb,timestamptz,uuid),public.create_quote(uuid,uuid,jsonb,timestamptz,uuid),private.publish_quote(uuid,uuid,integer),public.publish_quote(uuid,uuid,integer) to authenticated;
commit;
